using System.IO.Compression;
using System.Text.RegularExpressions;
using SkiaSharp;

namespace WC2.Tools;

/// <summary>
/// Runtime formats generated from the packaged sources. A generated file goes to
/// <c>generated/&lt;source path without extension&gt;.wctex</c>; the source is always kept as well. The
/// game prefers a generated file that sits in the same layer as its source, so a mod that replaces the
/// source image still wins.
///
/// <c>assets/build.json</c> lists what to generate:
/// <code>
/// "runtimeFormats": [ { "match": "^image/fonts/hd/cn/font(ht|kt)\\.png$", "format": "rgba4444" } ]
/// </code>
/// A format ending in <c>@load</c> (<c>rgba5551@load</c>) is not written as a file: the source is listed
/// in <c>generated/texture_formats.json</c> and the game converts it when it loads it (the package does
/// not grow; the GPU memory shrinks all the same).
/// <c>rgba4444</c>: 16 bit RGBA4444 pixels, deflate compressed, in a <c>.wctex</c> file (magic "WCTX",
/// version 1, format 1, width, height). Half the GPU memory of RGBA8 and no PNG decode at load time;
/// meant for large pages whose colour is plain (the white glyph pages of the Kai/Hei fonts).
/// </summary>
internal static class RuntimeFormats
{
    public const string Extension = ".wctex";

    /// <summary>Package path of the generated twin of a source path.</summary>
    public static string GeneratedPath(string source) => "generated/" + Path.ChangeExtension(source, Extension).Replace('\\', '/');

    /// <summary>Returns the number of generated files (written or already up to date).</summary>
    public static int Generate(string outDir, IReadOnlyList<(Regex match, string format)> rules, IReadOnlyDictionary<string, string> plan,
                               SortedDictionary<string, long> sizes, SortedDictionary<string, string> generatedFrom, bool force)
    {
        if (rules.Count == 0) return 0;
        int count = 0;
        var atLoad = new SortedDictionary<string, string>(StringComparer.Ordinal);
        foreach (var (target, source) in plan.ToList())
        {
            var rule = rules.FirstOrDefault(r => r.match.IsMatch(target));
            if (rule.match == null) continue;
            if (rule.format.EndsWith("@load", StringComparison.Ordinal))
            {
                // converted by the game when it loads the source (no extra file in the package)
                atLoad[target] = rule.format.Substring(0, rule.format.Length - 5);
                continue;
            }
            string generated = GeneratedPath(target);
            string dest = Path.Combine(outDir, generated);
            if (force || !File.Exists(dest) || File.GetLastWriteTimeUtc(dest) < File.GetLastWriteTimeUtc(source) || StoredFormat(dest) != FormatCode(rule.format))
            {
                switch (rule.format)
                {
                    case "rgba4444": WriteRgba4444(source, dest); break;
                    case "rgba5551": WriteRgba5551(source, dest); break;
                    case "alpha8": WriteAlpha8(source, dest); break;
                    default: throw new ToolException("unknown runtime format " + rule.format);
                }
                File.SetLastWriteTimeUtc(dest, File.GetLastWriteTimeUtc(source));
                Console.WriteLine($"  generated {generated} ({rule.format})");
            }
            sizes[generated] = new FileInfo(dest).Length;
            generatedFrom[generated] = target;
            count++;
        }
        // the list of load-time conversions
        string listPath = Path.Combine(outDir, TextureFormatsFile);
        var doc = new System.Text.Json.Nodes.JsonObject
        {
            ["format"] = 1,
            ["about"] = "Textures the game converts when it loads them (generated by build-pack from assets/build.json runtimeFormats ending in @load).",
            ["textures"] = new System.Text.Json.Nodes.JsonObject(atLoad.Select(kv => KeyValuePair.Create(kv.Key, (System.Text.Json.Nodes.JsonNode)kv.Value))),
        };
        string text = doc.ToJsonString(new System.Text.Json.JsonSerializerOptions { WriteIndented = true }) + "\n";
        Directory.CreateDirectory(Path.GetDirectoryName(listPath)!);
        if (!File.Exists(listPath) || File.ReadAllText(listPath) != text) File.WriteAllText(listPath, text);
        sizes[TextureFormatsFile] = new FileInfo(listPath).Length;
        return count + atLoad.Count;
    }

    private static int FormatCode(string format) => format switch { "rgba4444" => 1, "rgba5551" => 2, "alpha8" => 3, _ => 0 };

    /// <summary>The format code in a .wctex header (a changed rule regenerates the file).</summary>
    private static int StoredFormat(string path)
    {
        try
        {
            using var fs = File.OpenRead(path);
            var header = new byte[8];
            return fs.Read(header, 0, 8) == 8 ? BitConverter.ToUInt16(header, 6) : -1;
        }
        catch (IOException) { return -1; }
    }

    /// <summary>Package path of the load-time conversion list.</summary>
    public const string TextureFormatsFile = "generated/texture_formats.json";

    private static void WriteRgba4444(string source, string dest)
    {
        using var codec = SKCodec.Create(source) ?? throw new ToolException("cannot decode " + source);
        var info = new SKImageInfo(codec.Info.Width, codec.Info.Height, SKColorType.Rgba8888, SKAlphaType.Unpremul);
        using var bitmap = new SKBitmap(info);
        var result = codec.GetPixels(info, bitmap.GetPixels());
        if (result != SKCodecResult.Success && result != SKCodecResult.IncompleteInput) throw new ToolException("cannot decode " + source + ": " + result);
        byte[] rgba = bitmap.Bytes;
        int pixels = info.Width * info.Height;
        var packed = new byte[pixels * 2];
        for (int i = 0; i < pixels; i++)
        {
            int r = To4(rgba[i * 4]), g = To4(rgba[i * 4 + 1]), b = To4(rgba[i * 4 + 2]), a = To4(rgba[i * 4 + 3]);
            // GL_UNSIGNED_SHORT_4_4_4_4: R in the high nibble, A in the low one; little endian ushort
            ushort v = (ushort)((r << 12) | (g << 8) | (b << 4) | a);
            packed[i * 2] = (byte)(v & 0xFF);
            packed[i * 2 + 1] = (byte)(v >> 8);
        }
        Directory.CreateDirectory(Path.GetDirectoryName(dest)!);
        using var fs = File.Create(dest);
        using (var w = new BinaryWriter(fs, System.Text.Encoding.ASCII, leaveOpen: true))
        {
            w.Write("WCTX".ToCharArray());
            w.Write((ushort)1);   // version
            w.Write((ushort)1);   // format: RGBA4444
            w.Write(info.Width);
            w.Write(info.Height);
        }
        using var deflate = new DeflateStream(fs, CompressionLevel.SmallestSize);
        deflate.Write(packed, 0, packed.Length);
    }

    private static int To4(byte v) => (v * 15 + 127) / 255;
    private static int To5(byte v) => (v * 31 + 127) / 255;

    /// <summary>
    /// RGBA5551 (format 2): 32 levels per colour channel and a 1 bit alpha; for art with hard edges
    /// such as the greyscale area overlays of the map (half the memory of RGBA8).
    /// </summary>
    private static void WriteRgba5551(string source, string dest)
    {
        using var codec = SKCodec.Create(source) ?? throw new ToolException("cannot decode " + source);
        var info = new SKImageInfo(codec.Info.Width, codec.Info.Height, SKColorType.Rgba8888, SKAlphaType.Unpremul);
        using var bitmap = new SKBitmap(info);
        var result = codec.GetPixels(info, bitmap.GetPixels());
        if (result != SKCodecResult.Success && result != SKCodecResult.IncompleteInput) throw new ToolException("cannot decode " + source + ": " + result);
        byte[] rgba = bitmap.Bytes;
        int pixels = info.Width * info.Height;
        var packed = new byte[pixels * 2];
        for (int i = 0; i < pixels; i++)
        {
            int r = To5(rgba[i * 4]), g = To5(rgba[i * 4 + 1]), b = To5(rgba[i * 4 + 2]), a = rgba[i * 4 + 3] >= 128 ? 1 : 0;
            // GL_UNSIGNED_SHORT_5_5_5_1: R in the high bits, alpha in bit 0; little endian ushort
            ushort v = (ushort)((r << 11) | (g << 6) | (b << 1) | a);
            packed[i * 2] = (byte)(v & 0xFF);
            packed[i * 2 + 1] = (byte)(v >> 8);
        }
        WriteWctex(dest, 2, info.Width, info.Height, packed);
    }

    /// <summary>
    /// Alpha8 (format 3): only the alpha channel, 8 bits; for pages whose colour is plain white (the
    /// Kai/Hei glyph pages). A quarter of RGBA8; the game tints them with the text colour.
    /// </summary>
    private static void WriteAlpha8(string source, string dest)
    {
        using var codec = SKCodec.Create(source) ?? throw new ToolException("cannot decode " + source);
        var info = new SKImageInfo(codec.Info.Width, codec.Info.Height, SKColorType.Rgba8888, SKAlphaType.Unpremul);
        using var bitmap = new SKBitmap(info);
        var result = codec.GetPixels(info, bitmap.GetPixels());
        if (result != SKCodecResult.Success && result != SKCodecResult.IncompleteInput) throw new ToolException("cannot decode " + source + ": " + result);
        byte[] rgba = bitmap.Bytes;
        int pixels = info.Width * info.Height;
        var alpha = new byte[pixels];
        for (int i = 0; i < pixels; i++)
        {
            // a glyph page is white; where it is not, the luminance scales the alpha so nothing turns brighter
            int lum = (rgba[i * 4] * 299 + rgba[i * 4 + 1] * 587 + rgba[i * 4 + 2] * 114) / 1000;
            alpha[i] = (byte)(rgba[i * 4 + 3] * lum / 255);
        }
        WriteWctex(dest, 3, info.Width, info.Height, alpha);
    }

    private static void WriteWctex(string dest, ushort format, int width, int height, byte[] packed)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(dest)!);
        using var fs = File.Create(dest);
        using (var w = new BinaryWriter(fs, System.Text.Encoding.ASCII, leaveOpen: true))
        {
            w.Write("WCTX".ToCharArray());
            w.Write((ushort)1);   // version
            w.Write(format);
            w.Write(width);
            w.Write(height);
        }
        using var deflate = new DeflateStream(fs, CompressionLevel.SmallestSize);
        deflate.Write(packed, 0, packed.Length);
    }
}
